'use strict';
let lastAutomaticTarget=null,lastAutomaticBase=null,lastAutomaticImage=null;
function hasTransparentBackground(image){for(let p=3;p<image.data.length;p+=4)if(image.data[p]<20)return true;return false}
function automaticSource(){
 const scope=selection&&mode==='select'?'base':layers.length?'layer':'base';
 if(scope==='base'&&selection&&layers.length)return visibleAreaSource();
 if(scope==='layer'){
  const objects=chosen();if(!objects.length)throw Error('Выберите объекты на холсте или в списке слоёв.');
  const sources=objects.map(currentLayer=>{const parent={...currentLayer},image=parent.img.getContext('2d',{willReadFrequently:true}).getImageData(0,0,parent.img.width,parent.img.height);return{kind:'layer',parent,image,rect:{x:0,y:0,w:image.width,h:image.height},replaceIds:[parent.id],transparentBackground:hasTransparentBackground(image),baseReference:base}});
  return sources.length===1?sources[0]:{kind:'batch',sources,rect:{x:0,y:0,w:base.width,h:base.height},baseReference:base};
 }
 const cached=!selection&&splitSession?.kind==='base'?splitSession:null,shape=selection&&typeof selectionGeometry==='function'?selectionGeometry():cached?.shape,rect=shape?{...shape.bounds}:selection?{...selection}:cached?{...cached.rect}:{x:0,y:0,w:base.width,h:base.height};
 const image=bc().getImageData(rect.x,rect.y,rect.w,rect.h);if(cached)image.data.set(cached.pixels);
 return{kind:'base',image,rect,shape,previousSession:cached,replaceIds:cached?cached.ids:[],baseReference:base};
}
function automaticOptions(source){return{tolerance:+$('backgroundTolerance').value||55,detail:+$('splitTolerance').value,transparentBackground:source.transparentBackground===true,backgroundColor:source.backgroundColor}}
function automaticInput(source){return typeof maskForSegmentation==='function'?maskForSegmentation(source.image,source.rect,source.shape,source.backgroundColor):source.image}
// Sort only newly extracted, disjoint parts in the source's own coordinates.
// The layer stack is stored bottom-to-top; the list displays it in reverse.
function automaticReadingOrder(groups){const rows=[];for(const index of groups.map((_,i)=>i).sort((a,b)=>(groups[a].y+groups[a].h/2)-(groups[b].y+groups[b].h/2)||groups[a].x-groups[b].x||a-b)){const g=groups[index],cy=g.y+g.h/2;let row=rows.filter(r=>Math.abs(r.cy-cy)<=Math.min(r.h,g.h)*.45).sort((a,b)=>Math.abs(a.cy-cy)-Math.abs(b.cy-cy))[0];if(!row){row={cy,h:g.h,ids:[]};rows.push(row)}row.ids.push(index);row.cy=row.ids.reduce((n,i)=>n+groups[i].y+groups[i].h/2,0)/row.ids.length;row.h=Math.min(row.h,g.h)}return rows.sort((a,b)=>a.cy-b.cy).flatMap(r=>r.ids.sort((a,b)=>groups[a].x-groups[b].x||groups[a].y-groups[b].y||a-b))}
function makeAutomaticParts(source,result,firstId=seq){const ids=new Map();result.groups.forEach((g,i)=>g.ids.forEach(id=>ids.set(id,i)));const images=result.groups.map(g=>{const canvas=off(g.w,g.h);return{canvas,pixels:canvas.getContext('2d').createImageData(g.w,g.h)}}),cleaned=new Uint8ClampedArray(source.image.data);
 for(let p=0;p<result.labels.length;p++){const gi=ids.get(result.labels[p]);if(gi===undefined)continue;const g=result.groups[gi],x=p%source.rect.w,y=Math.floor(p/source.rect.w),di=((y-g.y)*g.w+x-g.x)*4;for(let k=0;k<4;k++){images[gi].pixels.data[di+k]=source.image.data[p*4+k];cleaned[p*4+k]=result.background[k]}}
 const created=result.groups.map((g,i)=>{images[i].canvas.getContext('2d').putImageData(images[i].pixels,0,0);const layer={id:firstId+i+1,name:source.kind==='layer'&&source.parent.name?source.parent.name+' · часть '+(i+1):'',img:images[i].canvas,x:source.rect.x+g.x+g.w/2,y:source.rect.y+g.y+g.h/2,scale:1,angle:0,opacity:1,visible:true,tint:null};if(source.kind==='layer'){const parent=source.parent,x=g.x+g.w/2-parent.img.width/2,y=g.y+g.h/2-parent.img.height/2,p=linearPoint(layerLinear(parent),x,y);Object.assign(layer,{x:parent.x+p.x,y:parent.y+p.y,scale:parent.scale,stretchX:parent.stretchX??1,stretchY:parent.stretchY??1,skew:parent.skew??0,angle:parent.angle,opacity:parent.opacity,visible:parent.visible,tint:parent.tint})}return layer});const ordered=automaticReadingOrder(result.groups).map((index,rank)=>{const layer=created[index];layer.id=firstId+rank+1;if(source.kind==='layer'&&source.parent.name)layer.name=source.parent.name+' · часть '+(rank+1);return layer}).reverse();return{created:ordered,cleaned};
}
function segmentAutomaticSource(source){if(source.kind!=='batch')return segmentObjects(automaticInput(source),automaticOptions(source));const batches=source.sources.map(item=>({source:item,result:segmentObjects(automaticInput(item),automaticOptions(item))}));return{batches,groups:batches.flatMap(item=>item.result.groups)}}
function applyAutomaticBatch(source,result){const batches=result.batches.filter(item=>item.result.groups.length),total=batches.reduce((n,item)=>n+item.result.groups.length,0);if(!total){toast('Части не найдены. Измените чувствительность.');return false}if(layers.length-batches.length+total>150){toast('Слишком много деталей. Уменьшите чувствительность.');return false}if(source.sources.some(item=>!layers.some(l=>l.id===item.parent.id&&l.img===item.parent.img)))return false;
 const replacements=new Map();let offset=seq;for(const item of batches){const parts=makeAutomaticParts(item.source,item.result,offset).created;replacements.set(item.source.parent.id,parts);offset+=parts.length}
 checkpoint(true);layers=layers.flatMap(l=>replacements.get(l.id)||[l]);seq=offset;active=null;selected.clear();selection=null;splitSession=null;setMode('move');ui();$('splitResult').textContent='Объектов: '+total;$('status').textContent='Разделено объектов: '+batches.length+'. Получено частей: '+total;toast('Выделенные объекты разделены. Остальные слои сохранены.');return true;
}
function applyAutomaticSource(source,result){if(source.kind==='batch')return applyAutomaticBatch(source,result);if(source.kind==='scene')return applySceneArea(source,result);if(!result.groups.length){toast('Отдельные объекты не найдены. Измените настройки.');return false}if(layers.length-source.replaceIds.length+result.groups.length>150){toast('Слишком много деталей. Уменьшите чувствительность или выберите другую область.');return false}
 const {created,cleaned}=makeAutomaticParts(source,result),originalPixels=new Uint8ClampedArray(source.image.data),replaced=new Set(source.replaceIds),anchor=source.replaceIds.length?Math.min(...source.replaceIds.map(id=>layers.findIndex(l=>l.id===id)).filter(i=>i>=0)):layers.length;
 checkpoint(true);if(source.kind==='base'){source.image.data.set(cleaned);bc().putImageData(source.image,source.rect.x,source.rect.y);layers=layers.filter(l=>!replaced.has(l.id));layers.push(...created);pending=null}else{layers=layers.filter(l=>!replaced.has(l.id));layers.splice(Math.min(anchor,layers.length),0,...created)}seq+=created.length;active=null;selected.clear();selection=null;splitSession={kind:source.kind,rect:{...source.rect},shape:source.shape,parent:source.parent,pixels:originalPixels,ids:created.map(l=>l.id)};setMode('move');ui();$('splitResult').textContent='Создано объектов: '+created.length;$('status').textContent=source.kind==='layer'?'Выбранный объект разделён на '+created.length+' частей. Остальные слои сохранены.':'Создано объектов: '+created.length;toast(source.kind==='layer'?'Объект разделён. Остальные слои не изменены.':'Объекты разделены. Фон заполнен.');return true;
}
let automaticBusy=false,splitSettingsDirty=true,splitFirstUse=true;
function resetSplitForSource(){splitSettingsDirty=true;splitFirstUse=true;for(const id of ['splitTolerance','backgroundTolerance']){const el=$(id);el.value=Math.round((+el.min+ +el.max)/2);$(id+'Value').textContent=el.value}}
function splitPartsLabel(count){const n=count%100,k=count%10;return count+' '+(n>=11&&n<=14?'частей':k===1?'часть':k>=2&&k<=4?'части':'частей')}
function syncSplitAction(){const available=!!selection&&mode==='select'||!layers.length||chosen().length>0,n=typeof splitPreview!=='undefined'?splitPreview?.groups.length:null,button=$('split');button.disabled=automaticBusy||!available||!n||!splitSettingsDirty;button.textContent=automaticBusy?'Применяем…':n===1?'Отделить от фона':'Применить разделение';button.classList.toggle('split-nudge',splitFirstUse&&!button.disabled);}

$('split').onclick=()=>{let source;try{source=automaticSource()}catch(e){toast(FragmentErrors.report(e,'Не удалось прочитать фото.'));return}if(source.rect.w<3||source.rect.h<3){toast('Область слишком маленькая');return}const options=automaticOptions(source),button=$('split');automaticBusy=true;button.disabled=true;button.textContent='Применяем…';setTimeout(()=>{try{if(base!==source.baseReference||(source.previousSession&&splitSession!==source.previousSession))return;if(source.kind==='layer'&&!source.previousSession&&!layers.some(l=>l.id===source.parent.id))return;const result=segmentAutomaticSource(source);if(applyAutomaticSource(source,result)){splitSettingsDirty=false;splitFirstUse=false}}catch(e){toast(FragmentErrors.report(e,'Не удалось разделить объекты.'))}finally{automaticBusy=false;updateAutomaticTarget()}},30)};
$('splitTolerance').oninput=()=>{splitSettingsDirty=true;$('splitToleranceValue').textContent=$('splitTolerance').value;if(typeof scheduleSplitPreview==='function')scheduleSplitPreview()};
$('backgroundTolerance').oninput=()=>{splitSettingsDirty=true;$('backgroundToleranceValue').textContent=$('backgroundTolerance').value;if(typeof scheduleSplitPreview==='function')scheduleSplitPreview()};
function updateAutomaticTarget(){
 const objects=chosen(),one=objects.length===1,many=objects.length>1,baseArea=!!selection&&mode==='select',available=baseArea||!layers.length||objects.length>0;
 syncSplitAction();
 $('split').dataset.tooltip=!available?'Выберите объекты на холсте или в списке слоёв.':baseArea?'Разделить выделенную область исходного фото.':layers.length?'Разделить каждый выбранный объект; остальные слои останутся на месте.':'Разделить загруженное изображение на объекты и сразу заполнить фон.';
 const key=baseArea?'area:'+JSON.stringify(selection):!layers.length?'base':objects.length?'layers:'+objects.map(l=>l.id).join(','):'none';
 const image=objects.length?objects.map(l=>l.img):base,sameImages=Array.isArray(image)&&Array.isArray(lastAutomaticImage)?image.length===lastAutomaticImage.length&&image.every((img,i)=>img===lastAutomaticImage[i]):lastAutomaticImage===image;if(lastAutomaticTarget===key&&lastAutomaticBase===base&&sameImages)return;lastAutomaticTarget=key;lastAutomaticBase=base;lastAutomaticImage=image;splitSettingsDirty=!layers.length;
 if(typeof clearSplitPreview==='function')clearSplitPreview();
 if(!automaticBusy&&available&&typeof scheduleSplitPreview==='function')queueMicrotask(()=>{if(lastAutomaticTarget===key&&!automaticBusy)scheduleSplitPreview()});
}
